def parse_arguments(*arguments):
    parser = argparse.ArgumentParser(description="Parse command-line arguments.")
    for arg, value in arguments:
        if isinstance(value, list):
            parser.add_argument(arg, metavar='value', nargs='*', type=type(value[0]), help=str(value[0]))
        else:
            parser.add_argument(arg, type=type(value), help=str(value))
    return parser

from collections import defaultdict
class MappingNode(dict):
    pass
def deep_merge_nodes(nodes):
    merged = defaultdict(MappingNode)
    for node in nodes:
        for key, value in node.items():
            if isinstance(value, MappingNode):
                merged[key].update(deep_merge_nodes([value]))
            else:
                merged[key].update(value)
    return dict(merged)

